import itertools

def calculate_sums_of_squares(limit):
    sums = set()
    for x in range(1, int(limit**0.5) + 1):
        for y in range(x + 1, int(limit**0.5) + 1):
            s = x*x + y*y
            if s <= limit:
                sums.add(s)
    return sorted(list(sums))

limit = 100
